def maxStudents(seats: list[list[str]]) -> int:
    m = len(seats)
    n = len(seats[0])
    broken = [0] * m
    for r in range(m):
        for c in range(n):
            if seats[r][c] == '#': broken[r] |= (1 << c)
    memo = {}
    def dp(row, prev_mask):
        if row == m: return 0
        state = (row, prev_mask)
        if state in memo: return memo[state]
        ans = 0
        for mask in range(1 << n):
            if (mask & broken[row]) != 0: continue
            if (mask & (mask >> 1)) != 0: continue
            if (mask & (prev_mask >> 1)) != 0: continue
            if (mask & (prev_mask << 1)) != 0: continue
            ans = max(ans, bin(mask).count('1') + dp(row + 1, mask))
        memo[state] = ans
        return ans
    return dp(0, 0)

